head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDFIS00300_P7.xml";
scwin.fn_GetPar;
scwin.fn_SetPar;
scwin.v_arrKey = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //조회조건이 담길 배열

/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_ColtrlGrtDtl1.removeAll();
    dts_ColtrlGrtDtl2.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    return true;
};


/**
 * 담보및지급보증 상세 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // 상단 조회
    scwin.fn_ContgntDebtDtl1();
};


/**
 * 담보및지급보증 상세 조회(상단)
 */
scwin.fn_ContgntDebtDtl1 = function() {
    // Lodaing~~~ 표시
    $c.cm.ShowWin(pan_Ctnt);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.coltrlGrtDtl1" + "&outputMessageId=FIS_CONTGNT_DEBT_DTL" + "&param01=" + scwin.v_arrKey[0] + "&param02=" + scwin.v_arrKey[1];
    dts_ColtrlGrtDtl1.DataID = encodeURI(url);
    dts_ColtrlGrtDtl1.Reset();
};


/**
 * 담보및지급보증 상세 조회(하단)
 */
scwin.fn_ContgntDebtDtl2 = function() {
    // Lodaing~~~ 표시
    $c.cm.ShowWin(pan_Ctnt1);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.coltrlGrtDtl2" + "&outputMessageId=FIS_CONTGNT_DEBT_DTL" + "&param01=" + scwin.v_arrKey[0] + "&param02=" + scwin.v_arrKey[1];
    dts_ColtrlGrtDtl2.DataID = encodeURI(url);
    dts_ColtrlGrtDtl2.Reset();
};


/**
 * 컨텐츠 append
 */
scwin.fn_AppendContents = function(pDs, pPanel) {
    var strContent = "<div style='overflow-x:auto;overflow-y:scroll;width:100%;height:350px;font-family:돋움체;'>";
    for (var nRow = 1; nRow <= pDs.getTotalRow(); nRow++) {
        strContent = strContent + pDs.getCellData(nRow, "CTNT") + "";
    }
    strContent = strContent + "</div>";
    pPanel.innerHTML = strContent;
    $c.cm.CloseWin(pDs.getTotalRow(), pPanel);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top); // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_Btm); // 패널라운드 처리	
    window.document.body.scroll = "no";
    var arrPar = new Array();
    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    var parentWin = $c.frame.path("../");
    scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        scwin.v_arrKey = arrPar;
    }
    if (scwin.v_arrKey.length >= 1) {
        scwin.fn_Search();
    } else {
        $c.win.alert("조회 조건이 없습니다");
    }
};
scwin.dts_ColtrlGrtDtl1_OnLoadError = function() {
    $c.cm.CloseWin(-1, pan_Ctnt);
    $c.stf.alert_error(dts_ColtrlGrtDtl1);
};
scwin.dts_ColtrlGrtDtl1_OnLoadCompleted = function(rowcount) {
    if (dts_ColtrlGrtDtl1.errorMsg) {
        $c.win.alert(dts_ColtrlGrtDtl1.errorMsg);
    }

    //담보및지급상세 하단 조회
    scwin.fn_ContgntDebtDtl2();

    // 멀티Row의 데이터를 하나로 합치자.
    scwin.fn_AppendContents(dts_ColtrlGrtDtl1, pan_Ctnt);
};
scwin.dts_ColtrlGrtDtl2_OnLoadError = function() {
    $c.cm.CloseWin(-1, pan_Ctnt1);
    $c.stf.alert_error(dts_ColtrlGrtDtl2);
};
scwin.dts_ColtrlGrtDtl2_OnLoadCompleted = function(rowcount) {
    if (dts_ColtrlGrtDtl2.errorMsg) {
        $c.win.alert(dts_ColtrlGrtDtl2.errorMsg);
    }

    // 멀티Row의 데이터를 하나로 합치자.
    scwin.fn_AppendContents(dts_ColtrlGrtDtl2, pan_Ctnt1);
};
scwin.img_Close_onclick = async function() {
    // 닫기 버튼 클릭
    await $c.frame.CloseFrame();
};
